{
  "name": "tx_init_data_buffer",
  "confidence": "medium",
  "docstring": "Clears and initializes a TX data buffer descriptor from a rate/PLCP parameter table and a small control field.",
  "subsystem": "mac",
  "var_renames": {
    "v1": "tx_buf_desc",
    "v4": "plcp_rate_val",
    "v5": "tx_param_len",
    "v6": "is_pow2_len"
  },
  "struct_hints": [
    {
      "offset": 16,
      "meaning": "a1: table row index, likely a rate/channel selector"
    },
    {
      "offset": 20,
      "meaning": "a1: length/antenna-like field tested for power-of-two encoding"
    },
    {
      "offset": 22,
      "meaning": "a1: table subcolumn index used together with the row index"
    },
    {
      "offset": 28,
      "meaning": "a1: pointer to the TX data buffer/descriptor"
    },
    {
      "offset": 0,
      "meaning": "v1: word field filled from global defaults selected by the power-of-two test"
    },
    {
      "offset": 4,
      "meaning": "v1: 16-bit PLCP/rate value fetched from the global parameter table"
    },
    {
      "offset": 262,
      "meaning": "v1: zeroed byte flag or padding field"
    },
    {
      "offset": 263,
      "meaning": "v1: copy of the a1+20 control/length value"
    },
    {
      "offset": 264,
      "meaning": "v1: set to a1+20 minus one when that value is a power of two, otherwise left cleared/default"
    }
  ]
}
